package cmd

import (
	"fmt"
	"os"
	"strconv"
	"strings"

	"github.com/TheZoraiz/ascii-image-converter/aic_package"
)

// Flags
var (
	flagColor     bool
	flagColorBg   bool
	flagDimensions []int
	flagWidth     int
	flagHeight    int
	flagMap       string
	flagBraille   bool
	flagThreshold int
	flagDither    bool
	flagGrayscale bool
	flagComplex   bool
	flagFull      bool
	flagNegative  bool
	flagFlipX     bool
	flagFlipY     bool
	flagSaveImg   string
	flagSaveTxt   string
	flagSaveGif   string
	flagSaveBg    []int
	flagFont      string
	flagFontColor []int
	flagOnlySave  bool
	flagFormats   bool
)

func Execute() {
	args := os.Args[1:]

	// Check for help/version flags first
	if len(args) == 0 {
		fmt.Fprintf(os.Stderr, "Error: Need at least 1 input path/url or piped input\nUse the -h flag for more info\n\n")
		os.Exit(1)
	}

	for _, arg := range args {
		if arg == "-h" || arg == "--help" {
			printHelp()
			return
		}
		if arg == "-v" || arg == "--version" {
			fmt.Println("\nv1.13.1")
			return
		}
	}

	// Parse flags and collect positional args
	imagePaths, flags, err := parseArgs(args)
	if err != nil {
		fmt.Fprintf(os.Stderr, "Error: %s\n\n", err.Error())
		os.Exit(1)
	}

	if flags.Formats {
		fmt.Println("Supported input formats:\n\nJPEG/JPG\nPNG\nWEBP\nBMP\nTIFF/TIF\nGIF\n")
		return
	}

	if len(imagePaths) == 0 {
		fmt.Fprintf(os.Stderr, "Error: Need at least 1 input path/url or piped input\nUse the -h flag for more info\n\n")
		os.Exit(1)
	}

	// Validate flags
	if err := validateFlags(flags); err != nil {
		fmt.Fprintf(os.Stderr, "Error: %s\n\n", err.Error())
		os.Exit(1)
	}

	// Process each image
	for _, imagePath := range imagePaths {
		printAscii(imagePath, flags)
	}
}

func parseArgs(args []string) ([]string, aic_package.Flags, error) {
	var imagePaths []string
	var flags aic_package.Flags

	// Set defaults
	flags.Threshold = 128
	flags.SaveBg = []int{0, 0, 0, 100}
	flags.FontColor = []int{255, 255, 255}

	i := 0
	for i < len(args) {
		arg := args[i]

		if !strings.HasPrefix(arg, "-") {
			imagePaths = append(imagePaths, arg)
			i++
			continue
		}

		switch arg {
		case "-C", "--color":
			flags.Color = true
		case "--color-bg":
			flags.ColorBg = true
		case "-g", "--grayscale":
			flags.Grayscale = true
		case "-c", "--complex":
			flags.Complex = true
		case "-f", "--full":
			flags.Full = true
		case "-n", "--negative":
			flags.Negative = true
		case "-x", "--flipX":
			flags.FlipX = true
		case "-y", "--flipY":
			flags.FlipY = true
		case "-b", "--braille":
			flags.Braille = true
		case "--dither":
			flags.Dither = true
		case "--only-save":
			flags.OnlySave = true
		case "--formats":
			flags.Formats = true

		case "-d", "--dimensions":
			i++
			if i >= len(args) {
				return nil, flags, fmt.Errorf("flag needs an argument: --dimensions")
			}
			vals, err := parseInts(args[i])
			if err != nil || len(vals) != 2 {
				return nil, flags, fmt.Errorf("invalid argument for --dimensions")
			}
			flags.Dimensions = vals

		case "-W", "--width":
			i++
			if i >= len(args) {
				return nil, flags, fmt.Errorf("flag needs an argument: --width")
			}
			v, err := strconv.Atoi(args[i])
			if err != nil {
				return nil, flags, fmt.Errorf("invalid argument for --width")
			}
			flags.Width = v

		case "-H", "--height":
			i++
			if i >= len(args) {
				return nil, flags, fmt.Errorf("flag needs an argument: --height")
			}
			v, err := strconv.Atoi(args[i])
			if err != nil {
				return nil, flags, fmt.Errorf("invalid argument for --height")
			}
			flags.Height = v

		case "-m", "--map":
			i++
			if i >= len(args) {
				return nil, flags, fmt.Errorf("flag needs an argument: --map")
			}
			flags.Map = args[i]

		case "--threshold":
			i++
			if i >= len(args) {
				return nil, flags, fmt.Errorf("flag needs an argument: --threshold")
			}
			v, err := strconv.Atoi(args[i])
			if err != nil {
				return nil, flags, fmt.Errorf("invalid argument for --threshold")
			}
			flags.Threshold = v

		case "-s", "--save-img":
			i++
			if i >= len(args) {
				return nil, flags, fmt.Errorf("flag needs an argument: --save-img")
			}
			flags.SaveImg = args[i]

		case "--save-txt":
			i++
			if i >= len(args) {
				return nil, flags, fmt.Errorf("flag needs an argument: --save-txt")
			}
			flags.SaveTxt = args[i]

		case "--save-gif":
			i++
			if i >= len(args) {
				return nil, flags, fmt.Errorf("flag needs an argument: --save-gif")
			}
			flags.SaveGif = args[i]

		case "--save-bg":
			i++
			if i >= len(args) {
				return nil, flags, fmt.Errorf("flag needs an argument: --save-bg")
			}
			vals, err := parseInts(args[i])
			if err != nil {
				return nil, flags, fmt.Errorf("invalid argument for --save-bg")
			}
			flags.SaveBg = vals

		case "--font":
			i++
			if i >= len(args) {
				return nil, flags, fmt.Errorf("flag needs an argument: --font")
			}
			flags.Font = args[i]

		case "--font-color":
			i++
			if i >= len(args) {
				return nil, flags, fmt.Errorf("flag needs an argument: --font-color")
			}
			vals, err := parseInts(args[i])
			if err != nil {
				return nil, flags, fmt.Errorf("invalid argument for --font-color")
			}
			flags.FontColor = vals

		default:
			// Check for '=' forms like --width=60
			if strings.Contains(arg, "=") {
				parts := strings.SplitN(arg, "=", 2)
				args[i] = parts[0]
				args = append(args[:i+1], append([]string{parts[1]}, args[i+1:]...)...)
				continue
			}
			return nil, flags, fmt.Errorf("unknown flag: %s", arg)
		}
		i++
	}

	return imagePaths, flags, nil
}

func parseInts(s string) ([]int, error) {
	parts := strings.Split(s, ",")
	var result []int
	for _, p := range parts {
		v, err := strconv.Atoi(strings.TrimSpace(p))
		if err != nil {
			return nil, err
		}
		result = append(result, v)
	}
	return result, nil
}

func validateFlags(flags aic_package.Flags) error {
	if flags.Dimensions != nil {
		if flags.Dimensions[0] <= 0 || flags.Dimensions[1] <= 0 {
			return fmt.Errorf("invalid values for dimensions")
		}
	}
	if flags.Width < 0 {
		return fmt.Errorf("invalid value for width")
	}
	if flags.Height < 0 {
		return fmt.Errorf("invalid value for height")
	}
	if flags.Threshold < 0 || flags.Threshold > 255 {
		return fmt.Errorf("threshold must be between 0 and 255")
	}
	if flags.SaveBg != nil {
		if len(flags.SaveBg) != 4 {
			return fmt.Errorf("--save-bg requires 4 values for RGBA, got %d", len(flags.SaveBg))
		}
		for _, v := range flags.SaveBg[:3] {
			if v < 0 || v > 255 {
				return fmt.Errorf("RBG values must be between 0 and 255")
			}
		}
		if flags.SaveBg[3] < 0 || flags.SaveBg[3] > 100 {
			return fmt.Errorf("Opacity value must be between 0 and 100")
		}
	}
	if flags.FontColor != nil {
		if len(flags.FontColor) != 3 {
			return fmt.Errorf("--font-color requires 3 values for RGB, got %d", len(flags.FontColor))
		}
	}
	return nil
}

func printAscii(imagePath string, flags aic_package.Flags) {
	err := aic_package.Convert(imagePath, flags)
	if err != nil {
		fmt.Fprintf(os.Stderr, "Error: %s\n\n", err.Error())
	}
}

func printHelp() {
	fmt.Print(`
This tool converts images into ascii art and prints them on the terminal.
Further configuration can be managed with flags.

Usage:
  ascii-image-converter [image paths/urls or piped stdin] [flags]

Flags:
  -C, --color             Display ascii art with original colors
                          If 24-bit colors aren't supported, uses 8-bit
                          (Inverts with --negative flag)
                          (Overrides --grayscale and --font-color flags)

      --color-bg          If some color flag is passed, use that color
                          on character background instead of foreground
                          (Inverts with --negative flag)
                          (Only applicable for terminal display)

  -d, --dimensions ints   Set width and height for ascii art in CHARACTER length
                          e.g. -d 60,30 (defaults to terminal height)
                          (Overrides --width and --height flags)

  -W, --width int         Set width for ascii art in CHARACTER length
                          Height is kept to aspect ratio
                          e.g. -W 60

  -H, --height int        Set height for ascii art in CHARACTER length
                          Width is kept to aspect ratio
                          e.g. -H 60

  -m, --map string        Give custom ascii characters to map against
                          Ordered from darkest to lightest
                          e.g. -m " .-+#@" (Quotation marks excluded from map)
                          (Overrides --complex flag)

  -b, --braille           Use braille characters instead of ascii
                          Terminal must support braille patterns properly
                          (Overrides --complex and --map flags)

      --threshold int     Threshold for braille art
                          Value between 0-255 is accepted
                          e.g. --threshold 170
                          (Defaults to 128)

      --dither            Apply dithering on image for braille
                          art conversion
                          (Only applicable with --braille flag)
                          (Negates --threshold flag)

  -g, --grayscale         Display grayscale ascii art
                          (Inverts with --negative flag)
                          (Overrides --font-color flag)

  -c, --complex           Display ascii characters in a larger range
                          May result in higher quality

  -f, --full              Use largest dimensions for ascii art
                          that fill the terminal width
                          (Overrides --dimensions, --width and --height flags)

  -n, --negative          Display ascii art in negative colors

  -x, --flipX             Flip ascii art horizontally

  -y, --flipY             Flip ascii art vertically

  -s, --save-img string   Save ascii art as a .png file
                          Format: <image-name>-ascii-art.png
                          Image will be saved in passed path
                          (pass . for current directory)

      --save-txt string   Save ascii art as a .txt file
                          Format: <image-name>-ascii-art.txt
                          File will be saved in passed path
                          (pass . for current directory)

      --save-gif string   If input is a gif, save it as a .gif file
                          Format: <gif-name>-ascii-art.gif
                          Gif will be saved in passed path
                          (pass . for current directory)

      --save-bg ints      Set background color for --save-img
                          and --save-gif flags
                          Pass an RGBA value
                          e.g. --save-bg 255,255,255,100
                          (Defaults to 0,0,0,100)

      --font string       Set font for --save-img and --save-gif flags
                          Pass file path to font .ttf file
                          e.g. --font ./RobotoMono-Regular.ttf
                          (Defaults to Hack-Regular for ascii and
                           DejaVuSans-Oblique for braille)

      --font-color ints   Set font color for terminal as well as
                          --save-img and --save-gif flags
                          Pass an RGB value
                          e.g. --font-color 0,0,0
                          (Defaults to 255,255,255)

      --only-save         Don't print ascii art on terminal
                          if some saving flag is passed

      --formats           Display supported input formats

  -h, --help              Help for ascii-image-converter

  -v, --version           Version for ascii-image-converter

Copyright © 2021 Zoraiz Hassan <hzoraiz8@gmail.com>
Distributed under the Apache License Version 2.0 (Apache-2.0)
For further details, visit https://github.com/TheZoraiz/ascii-image-converter
`)
}
GOEOF

