	baseName := filepath.Base(imagePath)
	ext := filepath.Ext(baseName)
	nameWithoutExt := strings.TrimSuffix(baseName, ext)

	// Check if it's a GIF
	extLower := strings.ToLower(ext)
	if extLower == ".gif" {
		return convertGif(f, imagePath, nameWithoutExt, flags, colorSupport)
	}

	return convertImageFile(f, imagePath, nameWithoutExt, flags, colorSupport)
}

func convertReader(r io.Reader, name string, flags Flags, colorSupport int) error {
	// Try to decode as image
	img, _, err := image.Decode(r)
	if err != nil {
		return fmt.Errorf("can't decode %s: %s", name, err.Error())
	}

	asciiArt, err := image_manipulation.ImageToAscii(img, flags)
	if err != nil {
		return err
	}

	return outputAscii(asciiArt, name, flags, colorSupport)
}

func convertImageFile(f *os.File, imagePath, nameWithoutExt string, flags Flags, colorSupport int) error {
	img, _, err := image.Decode(f)
	if err != nil {
		return fmt.Errorf("can't decode %s: %s", imagePath, err.Error())
	}

	asciiArt, err := image_manipulation.ImageToAscii(img, flags)
	if err != nil {
		return err
	}

	return outputAscii(asciiArt, nameWithoutExt, flags, colorSupport)
}

func outputAscii(asciiArt [][]image_manipulation.AsciiChar, name string, flags Flags, colorSupport int) error {
	// Handle color validation for color/grayscale/font-color flags
	needsColor := flags.Color || flags.Grayscale || (flags.FontColor != nil && len(flags.FontColor) == 3 && 
		!(flags.FontColor[0] == 255 && flags.FontColor[1] == 255 && flags.FontColor[2] == 255) &&
		flags.SaveImg == "" && flags.SaveTxt == "")

	// Actually check: only Color and Grayscale require terminal color support
	// FontColor without Color/Grayscale is just a color flag
	needsTermColor := flags.Color || flags.Grayscale
	// FontColor also needs terminal color
	if len(flags.FontColor) == 3 && (flags.FontColor[0] != 255 || flags.FontColor[1] != 255 || flags.FontColor[2] != 255) {
