package aic_package

import (
	"os"
	"strings"
)

// detectColorSupport returns:
// 2 = 24-bit truecolor
// 1 = 8-bit 256-color
// 0 = no color support
func detectColorSupport() int {
	// Check for 24-bit color support
	colorterm := os.Getenv("COLORTERM")
	if colorterm == "truecolor" || colorterm == "24bit" {
		return 2
	}

	// Check for 8-bit color support based on TERM
	term := os.Getenv("TERM")
	term8bit := []string{"xterm", "rxvt", "256", "color", "screen"}
	for _, keyword := range term8bit {
		if strings.Contains(term, keyword) {
			return 1
		}
	}

	return 0
}
EOF

