package image_manipulation

import (
	"fmt"
	"image"
	"image/color"
	"math"

	"github.com/TheZoraiz/ascii-image-converter/aic_package"
)

// AsciiChar holds a character and its associated color
type AsciiChar struct {
	Char  rune
	R, G, B uint8
}

const (
	DefaultMap = " .:-=+*#%@"
	ComplexMap = " .'`^\",;:Il!i><~+_-?][}{1)(|\\/tfjrxnuvczXYUJCLQ0OZmwqpdbkhao*#MW&8%B@$"
)

// ImageToAscii converts an image to a 2D grid of AsciiChar
func ImageToAscii(img image.Image, flags aic_package.Flags) ([][]AsciiChar, error) {
	bounds := img.Bounds()
	imgW := bounds.Max.X - bounds.Min.X
	imgH := bounds.Max.Y - bounds.Min.Y

	if imgW == 0 || imgH == 0 {
		return nil, fmt.Errorf("image has zero dimensions")
	}

	// Calculate output dimensions
	cols, rows, err := calculateDimensions(imgW, imgH, flags)
	if err != nil {
		return nil, err
	}

	if cols <= 0 || rows <= 0 {
		return nil, fmt.Errorf("invalid output dimensions")
	}

	// Resize image to target dimensions
	resized := resizeImage(img, cols, rows)

	// Convert to ASCII
	if flags.Braille {
		return convertToBraille(resized, cols, rows, flags)
	}
	return convertToAscii(resized, cols, rows, flags)
}

func calculateDimensions(imgW, imgH int, flags aic_package.Flags) (int, int, error) {
	if flags.Full {
