package image_manipulation

import (
	"fmt"
	"image"
	"image/color"
	"image/draw"
	"image/png"
	"os"
	"path/filepath"

	"github.com/TheZoraiz/ascii-image-converter/aic_package"
	"github.com/TheZoraiz/ascii-image-converter/fonts"
)

const (
	charW = 14
	charH = 28
	padX  = 5
	padY  = 5
)

// SaveToImage saves ASCII art as a PNG image file
func SaveToImage(asciiArt [][]AsciiChar, name, dir string, flags aic_package.Flags) (string, error) {
	rows := len(asciiArt)
	if rows == 0 {
		return "", fmt.Errorf("empty ascii art")
	}
	cols := len(asciiArt[0])

	// Image dimensions
	imgW := cols*charW + 2*padX
	imgH := rows*charH + 2*padY

	// Create background color
	var bgR, bgG, bgB uint8
	var bgA uint8 = 255
	if len(flags.SaveBg) == 4 {
		bgR = uint8(flags.SaveBg[0])
		bgG = uint8(flags.SaveBg[1])
		bgB = uint8(flags.SaveBg[2])
		// Opacity 0-100 -> 0-255
		bgA = uint8(flags.SaveBg[3] * 255 / 100)
	}

	img := image.NewRGBA(image.Rect(0, 0, imgW, imgH))
	bgColor := color.RGBA{bgR, bgG, bgB, bgA}
	draw.Draw(img, img.Bounds(), &image.Uniform{bgColor}, image.Point{}, draw.Src)

	// Determine font color
	var fR, fG, fB uint8 = 255, 255, 255
	if len(flags.FontColor) == 3 {
		fR = uint8(flags.FontColor[0])
		fG = uint8(flags.FontColor[1])
		fB = uint8(flags.FontColor[2])
	}

	// Get font face
	fontFace, err := fonts.GetFontFace(flags.Font, flags.Braille)
	if err != nil {
		return "", fmt.Errorf("failed to load font: %s", err.Error())
	}

	// Draw characters
	for row := 0; row < rows; row++ {
		for col := 0; col < cols; col++ {
			ch := asciiArt[row][col]

			x := padX + col*charW
			y := padY + row*charH

			// Determine color
			var r, g, b uint8
			if flags.Color {
				r, g, b = ch.R, ch.G, ch.B
				if flags.Negative {
					r = 255 - r
					g = 255 - g
					b = 255 - b
				}
			} else {
				r, g, b = fR, fG, fB
			}

			fontFace.DrawChar(img, ch.Char, x, y, r, g, b)
		}
	}

	// Save to file
	outPath := filepath.Join(dir, name+"-ascii-art.png")
	f, err := os.Create(outPath)
	if err != nil {
		return "", err
	}
	defer f.Close()

	if err := png.Encode(f, img); err != nil {
		return "", err
	}

	return outPath, nil
}
