package image_manipulation

import (
	"fmt"
	"github.com/TheZoraiz/ascii-image-converter/aic_package"
)

// CalculateDimensions returns the output width and height in characters
func CalculateDimensions(imgW, imgH int, flags aic_package.Flags) (int, int, error) {
	if flags.Full {
		termW, termH := GetTerminalSize()
		cols := termW
		if cols <= 0 {
			return 0, 0, fmt.Errorf("could not get terminal dimensions")
		}
		rows := cols * imgH / imgW / 2
		if rows <= 0 {
			rows = 1
		}
		if termH > 0 && rows > termH {
			rows = termH
			cols = rows * imgW * 2 / imgH
		}
		return cols, rows, nil
	}

	if flags.Dimensions != nil && len(flags.Dimensions) == 2 {
		return flags.Dimensions[0], flags.Dimensions[1], nil
	}

	if flags.Width > 0 {
		cols := flags.Width
		rows := cols * imgH / imgW / 2
		if rows <= 0 {
			rows = 1
		}
		return cols, rows, nil
	}

	if flags.Height > 0 {
		rows := flags.Height
		cols := rows * imgW * 2 / imgH
		if cols <= 0 {
			cols = 1
		}
		return cols, rows, nil
	}

	// Default: use terminal
	termW, termH := GetTerminalSize()
	cols := termW
	if cols <= 0 {
		return 0, 0, fmt.Errorf("could not get terminal dimensions, please use -d flag")
	}
	rows := cols * imgH / imgW / 2
	if rows <= 0 {
		rows = 1
	}
	if termH > 0 && rows > termH {
		rows = termH
		cols = rows * imgW * 2 / imgH
	}
	return cols, rows, nil
}
