package aic_package

import (
	"fmt"
	"image"
	_ "image/gif"
	_ "image/jpeg"
	_ "image/png"
	"io"
	"os"
	"path/filepath"
	"strings"

	"github.com/TheZoraiz/ascii-image-converter/image_manipulation"
)

// Convert converts an image to ASCII art
func Convert(imagePath string, flags Flags) error {
	colorSupport := detectColorSupport()

	// Check for only-save without save flag
	if flags.OnlySave && flags.SaveImg == "" && flags.SaveTxt == "" && flags.SaveGif == "" {
		return fmt.Errorf("you need to supply one of --save-img, --save-txt or --save-gif for using --only-save")
	}

	if imagePath == "-" {
		return convertFromReader(os.Stdin, "stdin", flags, colorSupport)
	}

	f, err := os.Open(imagePath)
	if err != nil {
		return fmt.Errorf("unable to open file: %s", err.Error())
	}
	defer f.Close()

	baseName := filepath.Base(imagePath)
	ext := filepath.Ext(baseName)
	nameWithoutExt := strings.TrimSuffix(baseName, ext)

	extLower := strings.ToLower(ext)
	if extLower == ".gif" {
		return convertGif(f, imagePath, nameWithoutExt, flags, colorSupport)
	}

	return convertFromReader(f, nameWithoutExt, flags, colorSupport)
}

func convertFromReader(r io.Reader, name string, flags Flags, colorSupport int) error {
	img, _, err := image.Decode(r)
	if err != nil {
		return fmt.Errorf("can't decode %s: %s", name, err.Error())
	}

	bounds := img.Bounds()
	imgW := bounds.Max.X - bounds.Min.X
	imgH := bounds.Max.Y - bounds.Min.Y

	cols, rows, err := image_manipulation.CalculateDimensions(imgW, imgH, flags)
	if err != nil {
		return err
	}

	var asciiArt [][]image_manipulation.AsciiChar

	if flags.Braille {
		// For braille, resize to cols*2 x rows*4
		pixels := image_manipulation.ResizeImage(img, cols*2, rows*4)
		if flags.Dither {
			asciiArt = image_manipulation.ConvertToBrailleWithDither(pixels, cols, rows, flags.Threshold, flags.Negative)
		} else {
			asciiArt = image_manipulation.ConvertToBrailleChars(pixels, cols, rows, flags)
		}
	} else {
		pixels := image_manipulation.ResizeImage(img, cols, rows)
		asciiArt = image_manipulation.ConvertToAsciiChars(pixels, flags)
	}

	if asciiArt == nil {
		return fmt.Errorf("conversion failed")
	}

	return outputAscii(asciiArt, name, flags, colorSupport)
}
