package aic_package

import (
	"fmt"
	"os"
	"path/filepath"
	"strings"

	"github.com/TheZoraiz/ascii-image-converter/image_manipulation"
)

func outputAscii(asciiArt [][]image_manipulation.AsciiChar, name string, flags Flags, colorSupport int) error {
	// Check if color output is needed but not supported
	needsColor := flags.Color || flags.Grayscale
	if !needsColor && len(flags.FontColor) == 3 {
		// FontColor only matters if it's not the default (255,255,255)
		if flags.FontColor[0] != 255 || flags.FontColor[1] != 255 || flags.FontColor[2] != 255 {
			needsColor = true
		}
	}

	if needsColor && colorSupport == 0 && flags.SaveImg == "" && flags.SaveTxt == "" && flags.SaveGif == "" {
		return fmt.Errorf("your terminal supports neither 24-bit nor 8-bit colors. Other coloring options aren't available")
	}

	// Print to terminal unless only-save
	if !flags.OnlySave || (flags.SaveImg == "" && flags.SaveTxt == "" && flags.SaveGif == "") {
		printToTerminal(asciiArt, flags, colorSupport)
	}

	// Save to txt
	if flags.SaveTxt != "" {
		path, err := saveToTxt(asciiArt, name, flags.SaveTxt)
		if err != nil {
			return fmt.Errorf("can't save file: %s", err.Error())
		}
		if flags.OnlySave {
			fmt.Printf("Saved %s\n", path)
		}
	}

	// Save to img
	if flags.SaveImg != "" {
		stat, err := os.Stat(flags.SaveImg)
		if err != nil {
			return fmt.Errorf("can't save file: %s", err.Error())
		}
		if !stat.IsDir() {
			return fmt.Errorf("can't save file: %s is not a directory", flags.SaveImg)
		}
		path, err := image_manipulation.SaveToImage(asciiArt, name, flags.SaveImg, flags)
		if err != nil {
			return fmt.Errorf("can't save file: %s", err.Error())
		}
		if flags.OnlySave {
			fmt.Printf("Saved %s\n", path)
		}
	}

	return nil
}

func printToTerminal(asciiArt [][]image_manipulation.AsciiChar, flags Flags, colorSupport int) {
	rows := len(asciiArt)
	for row := 0; row < rows; row++ {
		for _, ch := range asciiArt[row] {
			if flags.Color || flags.Grayscale || (len(flags.FontColor) == 3 && (flags.FontColor[0] != 255 || flags.FontColor[1] != 255 || flags.FontColor[2] != 255)) {
				printColoredChar(ch, flags, colorSupport)
			} else {
				fmt.Printf("%c", ch.Char)
			}
		}
		fmt.Println()
	}
}

func printColoredChar(ch image_manipulation.AsciiChar, flags Flags, colorSupport int) {
	var r, g, b uint8

	if flags.Color {
		r, g, b = ch.R, ch.G, ch.B
		if flags.Negative {
			r = 255 - r
			g = 255 - g
			b = 255 - b
		}
	} else if flags.Grayscale {
		lum := 0.299*float64(ch.R) + 0.587*float64(ch.G) + 0.114*float64(ch.B)
		if flags.Negative {
			lum = 255 - lum
		}
		r = uint8(lum)
		g = uint8(lum)
		b = uint8(lum)
	} else {
		// font-color
		if len(flags.FontColor) == 3 {
			r = uint8(flags.FontColor[0])
			g = uint8(flags.FontColor[1])
			b = uint8(flags.FontColor[2])
		}
	}

	if colorSupport >= 2 {
		// 24-bit color
		if flags.ColorBg {
			fmt.Printf("\033[48;2;%d;%d;%dm%c\033[0m", r, g, b, ch.Char)
		} else {
			fmt.Printf("\033[38;2;%d;%d;%dm%c\033[0m", r, g, b, ch.Char)
		}
	} else {
		// 8-bit color
		colorIdx := rgbToXterm256(r, g, b, flags.Color, flags.Grayscale)
		if flags.ColorBg {
			fmt.Printf("\033[48;5;%dm%c\033[0m", colorIdx, ch.Char)
		} else {
			fmt.Printf("\033[38;5;%dm%c\033[0m", colorIdx, ch.Char)
		}
	}
}

// rgbToXterm256 maps RGB to xterm 256 color index
func rgbToXterm256(r, g, b uint8, isColor, isGrayscale bool) int {
	if isGrayscale {
		// Use gray diagonal of 6x6x6 cube
		// Gray levels: 0, 95, 135, 175, 215, 255 -> indices: 0, 59, 102, 145, 188, 231
		grayLevels := []int{0, 95, 135, 175, 215, 255}
		grayIndices := []int{0, 59, 102, 145, 188, 231}
		lum := int(0.299*float64(r) + 0.587*float64(g) + 0.114*float64(b))

		bestIdx := 0
		bestDist := 999999
		for i, v := range grayLevels {
			d := v - lum
			if d < 0 {
				d = -d
			}
			if d < bestDist {
				bestDist = d
				bestIdx = grayIndices[i]
			}
		}
		return bestIdx
	}

	if isColor {
		// Use only 6x6x6 cube (16-231)
		// Find closest color in cube
		bestIdx := 16
		bestDist := 999999
		for i := 16; i < 232; i++ {
			cr, cg, cb := xterm256CubeRGB(i)
			dr := int(r) - cr
			dg := int(g) - cg
			db := int(b) - cb
			dist := dr*dr + dg*dg + db*db
			if dist < bestDist {
				bestDist = dist
				bestIdx = i
			}
		}
		return bestIdx
	}

	// font-color: use full 256 colors
	bestIdx := 0
	bestDist := 999999
	for i := 0; i < 256; i++ {
		cr, cg, cb := xterm256RGB(i)
		dr := int(r) - cr
		dg := int(g) - cg
		db := int(b) - cb
		dist := dr*dr + dg*dg + db*db
		if dist < bestDist {
			bestDist = dist
			bestIdx = i
		}
	}
	return bestIdx
}

func xterm256CubeLevel(n int) int {
	if n == 0 {
		return 0
	}
	return 55 + 40*n
}

func xterm256CubeRGB(idx int) (int, int, int) {
	idx -= 16
	b := idx % 6
	g := (idx / 6) % 6
	r := idx / 36
	return xterm256CubeLevel(r), xterm256CubeLevel(g), xterm256CubeLevel(b)
}

var xterm16Colors = [][3]int{
	{0, 0, 0}, {128, 0, 0}, {0, 128, 0}, {128, 128, 0},
	{0, 0, 128}, {128, 0, 128}, {0, 128, 128}, {192, 192, 192},
	{128, 128, 128}, {255, 0, 0}, {0, 255, 0}, {255, 255, 0},
	{0, 0, 255}, {255, 0, 255}, {0, 255, 255}, {255, 255, 255},
}

func xterm256RGB(idx int) (int, int, int) {
	if idx < 16 {
		c := xterm16Colors[idx]
		return c[0], c[1], c[2]
	}
	if idx < 232 {
		return xterm256CubeRGB(idx)
	}
	v := 8 + 10*(idx-232)
	return v, v, v
}

func saveToTxt(asciiArt [][]image_manipulation.AsciiChar, name, dir string) (string, error) {
	var sb strings.Builder
	rows := len(asciiArt)
	for row := 0; row < rows; row++ {
		for _, ch := range asciiArt[row] {
			sb.WriteRune(ch.Char)
		}
		if row < rows-1 {
			sb.WriteRune('\n')
		}
	}

	outPath := filepath.Join(dir, name+"-ascii-art.txt")
	return outPath, os.WriteFile(outPath, []byte(sb.String()), 0644)
}
GOEOF

