package aic_package

import (
	"fmt"
	"image/gif"
	"os"

	"github.com/TheZoraiz/ascii-image-converter/image_manipulation"
)

func convertGif(f *os.File, imagePath, nameWithoutExt string, flags Flags, colorSupport int) error {
	g, err := gif.DecodeAll(f)
	if err != nil {
		return fmt.Errorf("can't decode %s: %s", imagePath, err.Error())
	}

	if len(g.Image) == 0 {
		return fmt.Errorf("GIF has no frames")
	}

	canvasW := g.Config.Width
	canvasH := g.Config.Height

	// Compute dimensions from first frame
	cols, rows, err := image_manipulation.CalculateDimensions(canvasW, canvasH, flags)
	if err != nil {
		return err
	}

	totalFrames := len(g.Image)

	// Print progress header
	fmt.Fprintf(os.Stderr, "Generating ascii art... 0%%")

	var allFrames [][][]image_manipulation.AsciiChar

	for i, frame := range g.Image {
		// Check subimage dimensions
		frameBounds := frame.Bounds()
		if frameBounds.Max.X-frameBounds.Min.X < canvasW || frameBounds.Max.Y-frameBounds.Min.Y < canvasH {
			if i == 0 {
				// Report error
				fmt.Fprintf(os.Stderr, "\n")
				return fmt.Errorf("%s contains subimages smaller than default width and height\n\nProcess aborted because ascii-image-converter doesn't support subimage placement and transparency in GIFs", imagePath)
			}
		}

		// Process frame
		var asciiArt [][]image_manipulation.AsciiChar
		if flags.Braille {
			pixels := image_manipulation.ResizeImage(frame, cols*2, rows*4)
