package image_manipulation

import (
	"image"
	"image/color"
	"math"
)

// AsciiChar holds a character and its associated color info
type AsciiChar struct {
	Char    rune
	R, G, B uint8
}

const (
	DefaultMap = " .:-=+*#%@"
	ComplexMap = " .'`^\",;:Il!i><~+_-?][}{1)(|\\/tfjrxnuvczXYUJCLQ0OZmwqpdbkhao*#MW&8%B@$"
)

// braille dot bit mapping: [row][col]
var brailleBit = [4][2]uint8{
	{0x01, 0x08},
	{0x02, 0x10},
	{0x04, 0x20},
	{0x40, 0x80},
}

// ConvertToAsciiChars converts a 2D pixel array to ASCII characters
// charMap: character string (darkest to lightest)
// negative: invert before char selection
// flipX, flipY: flip the result
func ConvertToAsciiChars(pixels [][]color.RGBA, charMap string, negative, flipX, flipY bool) [][]AsciiChar {
	rows := len(pixels)
	if rows == 0 {
		return nil
	}
	cols := len(pixels[0])

	chars := []rune(charMap)
	n := len(chars)

	result := make([][]AsciiChar, rows)
	for row := 0; row < rows; row++ {
		result[row] = make([]AsciiChar, cols)
		for col := 0; col < cols; col++ {
			pix := pixels[row][col]
			r, g, b := pix.R, pix.G, pix.B

			// For character selection, apply negative first
			selR, selG, selB := r, g, b
			if negative {
				selR = 255 - r
				selG = 255 - g
				selB = 255 - b
			}

			lum := 0.299*float64(selR) + 0.587*float64(selG) + 0.114*float64(selB)
			idx := int(lum * float64(n) / 256.0)
			if idx >= n {
				idx = n - 1
			}

			result[row][col] = AsciiChar{
				Char: chars[idx],
				R:    r,
				G:    g,
				B:    b,
			}
		}
	}

	// Apply flips
	if flipX {
		for row := 0; row < rows; row++ {
			for col := 0; col < cols/2; col++ {
				result[row][col], result[row][cols-1-col] = result[row][cols-1-col], result[row][col]
			}
		}
	}
	if flipY {
		for row := 0; row < rows/2; row++ {
			result[row], result[rows-1-row] = result[rows-1-row], result[row]
		}
	}

	return result
}

// ConvertToBrailleChars converts pixel array (size cols*2 x rows*4) to braille characters
func ConvertToBrailleChars(pixels [][]color.RGBA, cols, rows, threshold int, negative, flipX, flipY bool) [][]AsciiChar {
	result := make([][]AsciiChar, rows)
	for row := 0; row < rows; row++ {
		result[row] = make([]AsciiChar, cols)
		for col := 0; col < cols; col++ {
			var bits uint8

			for dy := 0; dy < 4; dy++ {
				for dx := 0; dx < 2; dx++ {
					pixRow := row*4 + dy
					pixCol := col*2 + dx

					pix := pixels[pixRow][pixCol]
					r, g, b := pix.R, pix.G, pix.B

					if negative {
						r = 255 - r
						g = 255 - g
						b = 255 - b
					}

					lum := 0.299*float64(r) + 0.587*float64(g) + 0.114*float64(b)
					if int(math.Round(lum)) >= threshold {
						bits |= brailleBit[dy][dx]
					}
				}
			}

			// Use the color of the top-left pixel of this cell
			avgPix := pixels[row*4][col*2]

			result[row][col] = AsciiChar{
				Char: rune(0x2800 + int(bits)),
				R:    avgPix.R,
				G:    avgPix.G,
				B:    avgPix.B,
			}
		}
	}

	// Apply flips
	if flipX {
		for row := 0; row < rows; row++ {
			for col := 0; col < cols/2; col++ {
				result[row][col], result[row][cols-1-col] = result[row][cols-1-col], result[row][col]
			}
		}
	}
	if flipY {
		for row := 0; row < rows/2; row++ {
			result[row], result[rows-1-row] = result[rows-1-row], result[row]
		}
	}

	return result
}

// ResizeImage resizes an image using float-based area averaging
func ResizeImage(img image.Image, outW, outH int) [][]color.RGBA {
	bounds := img.Bounds()
	imgW := bounds.Max.X - bounds.Min.X
	imgH := bounds.Max.Y - bounds.Min.Y

	result := make([][]color.RGBA, outH)
	for row := 0; row < outH; row++ {
		result[row] = make([]color.RGBA, outW)
		for col := 0; col < outW; col++ {
			xLo := float64(col) * float64(imgW) / float64(outW)
			xHi := float64(col+1) * float64(imgW) / float64(outW)
			yLo := float64(row) * float64(imgH) / float64(outH)
			yHi := float64(row+1) * float64(imgH) / float64(outH)

			var rSum, gSum, bSum, wSum float64

			ixLo := int(xLo)
			ixHi := int(xHi)
			if float64(ixHi) == xHi && xHi > xLo {
				ixHi--
			}

			iyLo := int(yLo)
			iyHi := int(yHi)
			if float64(iyHi) == yHi && yHi > yLo {
				iyHi--
			}

			for x := ixLo; x <= ixHi; x++ {
				wx := math.Min(float64(x+1), xHi) - math.Max(float64(x), xLo)
				for y := iyLo; y <= iyHi; y++ {
					wy := math.Min(float64(y+1), yHi) - math.Max(float64(y), yLo)
					w := wx * wy

					r32, g32, b32, _ := img.At(bounds.Min.X+x, bounds.Min.Y+y).RGBA()
					rSum += float64(r32>>8) * w
					gSum += float64(g32>>8) * w
					bSum += float64(b32>>8) * w
					wSum += w
				}
			}

			if wSum > 0 {
				result[row][col] = color.RGBA{
					R: uint8(math.Round(rSum / wSum)),
					G: uint8(math.Round(gSum / wSum)),
					B: uint8(math.Round(bSum / wSum)),
					A: 255,
				}
			}
		}
	}
	return result
}
