	for row := 0; row < outH; row++ {
		result[row] = make([]color.RGBA, outW)
		for col := 0; col < outW; col++ {
			xLo := float64(col) * float64(imgW) / float64(outW)
			xHi := float64(col+1) * float64(imgW) / float64(outW)
			yLo := float64(row) * float64(imgH) / float64(outH)
			yHi := float64(row+1) * float64(imgH) / float64(outH)

			var rSum, gSum, bSum, wSum float64

			ixLo := int(xLo)
			ixHi := int(xHi)
			if float64(ixHi) == xHi && xHi > xLo {
				ixHi--
			}

			iyLo := int(yLo)
			iyHi := int(yHi)
			if float64(iyHi) == yHi && yHi > yLo {
				iyHi--
			}

			for x := ixLo; x <= ixHi; x++ {
				wx := math.Min(float64(x+1), xHi) - math.Max(float64(x), xLo)
				for y := iyLo; y <= iyHi; y++ {
					wy := math.Min(float64(y+1), yHi) - math.Max(float64(y), yLo)
					w := wx * wy

