package image_manipulation

import (
	"image/color"
	"math"
)

// FloydSteinbergDither applies Floyd-Steinberg dithering to pixels
// and returns a binary (filled/empty) result
func FloydSteinbergDither(pixels [][]color.RGBA, threshold int, negative bool) [][]bool {
	rows := len(pixels)
	if rows == 0 {
		return nil
	}
	cols := len(pixels[0])

	// Convert to grayscale floats
	gray := make([][]float64, rows)
	for y := 0; y < rows; y++ {
		gray[y] = make([]float64, cols)
		for x := 0; x < cols; x++ {
			pix := pixels[y][x]
			r, g, b := pix.R, pix.G, pix.B
			if negative {
				r = 255 - r
				g = 255 - g
				b = 255 - b
			}
			gray[y][x] = 0.299*float64(r) + 0.587*float64(g) + 0.114*float64(b)
		}
	}

	result := make([][]bool, rows)
	for y := 0; y < rows; y++ {
		result[y] = make([]bool, cols)
	}

	for y := 0; y < rows; y++ {
		for x := 0; x < cols; x++ {
			oldVal := gray[y][x]
			var newVal float64
			if oldVal >= float64(threshold) {
				newVal = 255.0
				result[y][x] = true
			} else {
				newVal = 0.0
				result[y][x] = false
			}
			err := oldVal - newVal

			if x+1 < cols {
				gray[y][x+1] += err * 7.0 / 16.0
			}
			if y+1 < rows {
				if x > 0 {
					gray[y+1][x-1] += err * 3.0 / 16.0
				}
				gray[y+1][x] += err * 5.0 / 16.0
				if x+1 < cols {
					gray[y+1][x+1] += err * 1.0 / 16.0
				}
			}
		}
	}

	return result
}

// ConvertToBrailleWithDither converts pixels to braille using dithering
func ConvertToBrailleWithDither(pixels [][]color.RGBA, cols, rows, threshold int, negative, flipX, flipY bool) [][]AsciiChar {
	dithered := FloydSteinbergDither(pixels, threshold, negative)

	result := make([][]AsciiChar, rows)
	for row := 0; row < rows; row++ {
		result[row] = make([]AsciiChar, cols)
		for col := 0; col < cols; col++ {
			var bits uint8

			for dy := 0; dy < 4; dy++ {
				for dx := 0; dx < 2; dx++ {
					pixRow := row*4 + dy
					pixCol := col*2 + dx

					if dithered[pixRow][pixCol] {
						bits |= brailleBit[dy][dx]
					}
				}
			}

