package image_manipulation

import (
	"fmt"
	"image"
	"image/color"
	"image/draw"
	"image/png"
	"os"
	"path/filepath"
)

const (
	charW = 14
	charH = 28
	padX  = 5
	padY  = 5
)

// ImageSaveParams holds parameters for saving ASCII art as image
type ImageSaveParams struct {
	BgR, BgG, BgB, BgA uint8
	FgR, FgG, FgB       uint8
	UseOrigColors       bool
	Negative            bool
	FontPath            string
	Braille             bool
}

// SaveToImage saves ASCII art as a PNG image file
func SaveToImage(asciiArt [][]AsciiChar, name, dir string, params ImageSaveParams) (string, error) {
	rows := len(asciiArt)
	if rows == 0 {
		return "", fmt.Errorf("empty ascii art")
	}
	cols := len(asciiArt[0])

	imgW := cols*charW + 2*padX
	imgH := rows*charH + 2*padY

	img := image.NewRGBA(image.Rect(0, 0, imgW, imgH))
	bgColor := color.RGBA{params.BgR, params.BgG, params.BgB, params.BgA}
	draw.Draw(img, img.Bounds(), &image.Uniform{bgColor}, image.Point{}, draw.Src)

	fR, fG, fB := params.FgR, params.FgG, params.FgB

	// Draw characters using bitmap font
	for row := 0; row < rows; row++ {
		for col := 0; col < cols; col++ {
			ch := asciiArt[row][col]

			x := padX + col*charW
			y := padY + row*charH

			var r, g, b uint8
			if params.UseOrigColors {
				r, g, b = ch.R, ch.G, ch.B
				if params.Negative {
					r = 255 - r
					g = 255 - g
					b = 255 - b
				}
			} else {
				r, g, b = fR, fG, fB
			}

			drawBitmapChar(img, ch.Char, x, y, r, g, b)
		}
	}

	outPath := filepath.Join(dir, name+"-ascii-art.png")
	f, err := os.Create(outPath)
	if err != nil {
		return "", err
	}
	defer f.Close()

	if err := png.Encode(f, img); err != nil {
		return "", err
	}

	return outPath, nil
}

func drawBitmapChar(img *image.RGBA, char rune, x, y int, r, g, b uint8) {
	charIdx := int(char) - 32
	if charIdx < 0 || charIdx >= 96 {
		return
	}

	bm := vgaFont8x16[charIdx]
	fc := color.RGBA{r, g, b, 255}

	// Scale 8x16 bitmap to charW x charH (14x28)
	// Simple nearest-neighbor scaling
	for py := 0; py < charH; py++ {
		srcY := py * 16 / charH
		if srcY >= 16 {
			srcY = 15
		}
		row := bm[srcY]
		for px := 0; px < charW; px++ {
			srcX := px * 8 / charW
			if srcX >= 8 {
				srcX = 7
			}
			if row&(0x80>>uint(srcX)) != 0 {
				img.Set(x+px, y+py, fc)
			}
		}
	}
}
