	bestIdx := 0
	bestDist := 999999
	for i := 0; i < 256; i++ {
		cr, cg, cb := xterm256RGB(i)
		dr := int(r) - cr
		dg := int(g) - cg
		db := int(b) - cb
		dist := dr*dr + dg*dg + db*db
		if dist < bestDist {
			bestDist = dist
			bestIdx = i
		}
	}
	return bestIdx
}

