		fmt.Fprintf(os.Stderr, "\rGenerating ascii art... %d%%", progress)
	}

	// Clear the progress line
	fmt.Fprintf(os.Stderr, "                               \r")

	// Display frames
	for _, frame := range allFrames {
		if err := outputAscii(frame, nameWithoutExt, flags, colorSupport); err != nil {
