package aic_package

import (
	"fmt"
	"image/gif"
	"os"

	"github.com/TheZoraiz/ascii-image-converter/image_manipulation"
)

func convertGif(f *os.File, imagePath, nameWithoutExt string, flags Flags, colorSupport int) error {
	g, err := gif.DecodeAll(f)
	if err != nil {
		return fmt.Errorf("can't decode %s: %s", imagePath, err.Error())
	}

	if len(g.Image) == 0 {
		return fmt.Errorf("GIF has no frames")
	}

	canvasW := g.Config.Width
	canvasH := g.Config.Height

	// Compute dimensions from canvas size
	cols, rows, err := image_manipulation.CalculateDimensions(canvasW, canvasH,
		flags.Full, flags.Dimensions, flags.Width, flags.Height, flags.Braille)
	if err != nil {
		return err
	}

	// Choose character map
	charMap := image_manipulation.DefaultMap
	if flags.Complex {
		charMap = image_manipulation.ComplexMap
	}
	if flags.Map != "" {
		charMap = flags.Map
	}

	totalFrames := len(g.Image)

	// Print progress header to STDOUT (not stderr!)
	fmt.Printf("Generating ascii art... 0%%")

	var allFrames [][][]image_manipulation.AsciiChar

	for i, frame := range g.Image {
		// Check subimage dimensions
		frameBounds := frame.Bounds()
		frameW := frameBounds.Max.X - frameBounds.Min.X
		frameH := frameBounds.Max.Y - frameBounds.Min.Y

		if frameW < canvasW || frameH < canvasH {
			fmt.Printf("\n")
			errMsg := fmt.Sprintf("%s contains subimages smaller than default width and height\n\nProcess aborted because ascii-image-converter doesn't support subimage placement and transparency in GIFs", imagePath)
			if i == 0 {
				return fmt.Errorf("%s", errMsg)
			}
			fmt.Fprintf(os.Stderr, "Error: %s\n\n", errMsg)
			break
		}

		// Process frame
		var asciiArt [][]image_manipulation.AsciiChar
		if flags.Braille {
			pixels := image_manipulation.ResizeImage(frame, cols*2, rows*4)
			if flags.Dither {
				asciiArt = image_manipulation.ConvertToBrailleWithDither(
					pixels, cols, rows, flags.Threshold, flags.Negative, flags.FlipX, flags.FlipY)
			} else {
				asciiArt = image_manipulation.ConvertToBrailleChars(
					pixels, cols, rows, flags.Threshold, flags.Negative, flags.FlipX, flags.FlipY)
			}
		} else {
			pixels := image_manipulation.ResizeImage(frame, cols, rows)
			asciiArt = image_manipulation.ConvertToAsciiChars(pixels, charMap, flags.Negative, flags.FlipX, flags.FlipY)
		}

		allFrames = append(allFrames, asciiArt)

		// Update progress
		progress := (i + 1) * 100 / totalFrames
		fmt.Printf("\rGenerating ascii art... %d%%", progress)
	}

	// Clear the progress line (use spaces to overwrite)
	fmt.Printf("\r                              \r")

	// Display frames in a loop (like the original tool)
	for {
		for _, frame := range allFrames {
			if err := outputAscii(frame, nameWithoutExt, flags, colorSupport); err != nil {
				return err
			}
		}
	}
}
