cat > /workspace/image_manipulation/bmp_decoder.go << 'GOEOF'
package image_manipulation

import (
	"encoding/binary"
	"fmt"
	"image"
	"image/color"
	"io"
)

// DecodeBMP decodes a BMP image
func DecodeBMP(r io.Reader) (image.Image, error) {
	data, err := io.ReadAll(r)
	if err != nil {
		return nil, err
	}

	if len(data) < 54 {
		return nil, fmt.Errorf("invalid BMP: too short")
	}

	// Check magic
	if data[0] != 'B' || data[1] != 'M' {
		return nil, fmt.Errorf("invalid BMP: wrong magic")
	}

	// Parse file header
	dataOffset := binary.LittleEndian.Uint32(data[10:14])

	// Parse DIB header (BITMAPINFOHEADER)
	headerSize := binary.LittleEndian.Uint32(data[14:18])
	if headerSize < 40 {
		return nil, fmt.Errorf("unsupported BMP header size: %d", headerSize)
	}

	width := int(int32(binary.LittleEndian.Uint32(data[18:22])))
	height := int(int32(binary.LittleEndian.Uint32(data[22:26])))
	bitsPerPixel := binary.LittleEndian.Uint16(data[28:30])
	compression := binary.LittleEndian.Uint32(data[30:34])

	if compression != 0 {
		return nil, fmt.Errorf("unsupported BMP compression: %d", compression)
	}

	if bitsPerPixel != 24 && bitsPerPixel != 32 {
		return nil, fmt.Errorf("unsupported BMP bits per pixel: %d", bitsPerPixel)
	}

	// Handle top-down vs bottom-up
	topDown := false
	if height < 0 {
		height = -height
		topDown = true
	}

	img := image.NewRGBA(image.Rect(0, 0, width, height))

	bytesPerPixel := int(bitsPerPixel) / 8
	rowSize := ((width*bytesPerPixel + 3) / 4) * 4 // align to 4 bytes

	for y := 0; y < height; y++ {
		srcY := y
		if !topDown {
			srcY = height - 1 - y
		}
		rowOffset := int(dataOffset) + srcY*rowSize
		if rowOffset+width*bytesPerPixel > len(data) {
			return nil, fmt.Errorf("BMP data too short")
		}

		for x := 0; x < width; x++ {
			offset := rowOffset + x*bytesPerPixel
			b := data[offset]
			g := data[offset+1]
			r := data[offset+2]
			a := uint8(255)
			if bytesPerPixel == 4 {
				a = data[offset+3]
			}
			img.Set(x, y, color.RGBA{r, g, b, a})
		}
	}

	return img, nil
}
GOEOF

